,"source":"reply-current-publication","target":"reply-note","sourceHandle":"true"},{"id":"edge-reply-claimed-reply-generate-true","source":"reply-claimed","target":"reply-generate","sourceHandle":"true"},{"id":"edge-reply-generate-reply-latest-publication-success","source":"reply-generate","target":"reply-latest-publication","sourceHandle":"success"},{"id":"edge-reply-generate-reply-release-error","source":"reply-generate","target":"reply-release","sourceHandle":"error"},{"id":"edge-reply-release-reply-error-4-success","source":"reply-release","target":"reply-error-4","sourceHandle":"success"},{"id":"edge-reply-release-reply-error-4-error","source":"reply-release","target":"reply-error-4","sourceHandle":"error"},{"id":"edge-reply-note-reply-end-4-success","source":"reply-note","target":"reply-end-4","sourceHandle":"success"},{"id":"edge-reply-note-reply-error-4-error","source":"reply-note","target":"reply-error-4","sourceHandle":"error"}]}
$graph$, E'\n'),
       3,
       folder.id,
       (SELECT coalesce(max(display_order), -1) + 1 FROM automation_trigger WHERE folder_id IS NOT DISTINCT FROM folder.id)
FROM (SELECT (SELECT child.id
              FROM automation_folder child
                       JOIN automation_folder parent ON parent.id = child.parent_id
              WHERE child.name = 'Работа с сообщениями'
                AND parent.name = 'Jev'
              LIMIT 1) AS id) folder
WHERE NOT EXISTS (SELECT 1 FROM automation_trigger WHERE name = 'Подсказка ответа по истории чатов (Jev)');
